function validate([score, k]) {
  if (!Array.isArray(score) || score.length < 1 || score.length > 250) return 'score needs 1 to 250 rows.';
  const n = Array.isArray(score[0]) ? score[0].length : 0;
  if (n < 1 || n > 250) return 'Each row has 1 to 250 marks.';
  const seen = new Set();
  for (const row of score) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row needs the same number of marks.';
    for (const value of row) {
      if (!Number.isInteger(value) || value < 1 || value > 100000) return 'Each mark is between 1 and 10^5.';
      if (seen.has(value)) return 'All marks in score must be different.';
      seen.add(value);
    }
  }
  if (!Number.isInteger(k) || k < 0 || k >= n) return 'k is a column index from 0 to n - 1.';
  return null;
}

