function sortTheStudents(score, k) {
  // Copy the list of rows so the caller's matrix keeps its order.
  const students = score.slice();
  students.sort((first, second) => {
    const firstScore = first[k];
    const secondScore = second[k];
    // The marks are distinct, so this is never 0: a higher mark on exam k goes first.
    return secondScore - firstScore;
  });
  return students;
}

