function sortTheStudents(score, k) {
  // Selection sort: repeatedly bring the best remaining row to the front.
  const rows = score.map(row => row.slice());
  for (let i = 0; i < rows.length; i++) {
    let top = i;
    for (let j = i + 1; j < rows.length; j++) if (rows[j][k] > rows[top][k]) top = j;
    [rows[i], rows[top]] = [rows[top], rows[i]];
  }
  return rows;
}

