function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'large') {
    const shape = pick(0, 2);
    if (shape === 0) { m = 100; n = 100; }
    else if (shape === 1) { m = 100; n = pick(1, 5); }
    else { m = pick(50, 100); n = pick(20, 100); }
  } else {
    m = pick(1, 6);
    n = pick(1, 4);
  }
  // Draw m * n distinct marks, sometimes from a tight range so they sit close together.
  const top = size === 'small' && rand() < 0.5 ? m * n + pick(0, 10) : 100000;
  const seen = new Set();
  const values = [];
  while (values.length < m * n) {
    const value = pick(1, top);
    if (seen.has(value)) continue;
    seen.add(value);
    values.push(value);
  }
  const score = Array.from({ length: m }, (_, i) => values.slice(i * n, i * n + n));
  return [score, pick(0, n - 1)];
}
